CREATE TABLE IF NOT EXISTS publications (id TEXT PRIMARY KEY, source TEXT NOT NULL, external_id TEXT NOT NULL, kind TEXT NOT NULL, category TEXT NOT NULL, title TEXT NOT NULL, summary TEXT NOT NULL DEFAULT '', level TEXT NOT NULL DEFAULT '', area TEXT NOT NULL DEFAULT '', junta TEXT NOT NULL DEFAULT '', location TEXT NOT NULL DEFAULT '', shift TEXT NOT NULL DEFAULT '', character TEXT NOT NULL DEFAULT '', starts_at TEXT, ends_at TEXT, status TEXT NOT NULL, official_url TEXT NOT NULL, metadata TEXT NOT NULL, content_hash TEXT NOT NULL, source_updated_at TEXT, source_published_at TEXT, registration_open_at TEXT, registration_close_at TEXT, expires_at TEXT, source_status TEXT NOT NULL DEFAULT 'UNKNOWN', normalized_status TEXT NOT NULL DEFAULT 'UNKNOWN', removed_at TEXT, last_seen_at TEXT NOT NULL DEFAULT '', last_changed_at TEXT NOT NULL DEFAULT '', first_seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sync_state (source TEXT PRIMARY KEY, synced_at TEXT NOT NULL, item_count INTEGER NOT NULL DEFAULT 0, error TEXT, last_attempt_at TEXT, last_successful_sync_at TEXT, sync_status TEXT NOT NULL DEFAULT 'UNKNOWN', error_code TEXT, error_message TEXT);
